.ds {
  --ds-bg:var(--p-bg,#ffffff);
  --ds-surface:var(--p-surface,#f1f3f6);
  --ds-high:var(--p-high,#fafbfc);
  --ds-text:var(--p-ink,#2c333d);
  --ds-muted:var(--p-muted,#59636f);
  --ds-border:var(--p-line,#c2cad5);
  --ds-control-border:var(--p-control-border,#7b8592);
  --ds-soft:var(--p-soft,#d3e8de);
  --ds-accent:var(--p-accent,#303b48);
  --ds-on-accent:var(--p-on-accent,#ffffff);
  --ds-focus:var(--p-highlight,#6153b5);
  --ds-error:var(--p-error,#a3313e);
  --ds-success:var(--p-success,#26614f);
  --ds-warning:var(--p-warning,#805719);
  --ds-radius:var(--p-radius,24px);
  --ds-control-radius:var(--p-control-radius,16px);
  --ds-shadow:var(--p-shadow,6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed);
  --ds-raised:var(--p-raised,3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed);
  --ds-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-glass:var(--p-glass,#f6f8fbe8);
  --ds-disabled:var(--p-disabled,#dce1e8);
  --ds-duration:var(--p-duration,140ms);
  --ds-font:var(--p-font,Pretendard, sans-serif);
  --ds-display-font:var(--p-display-font,Outfit, Pretendard, sans-serif);
  --ds-text-sm:var(--p-text-sm,13px);
  --ds-text-md:var(--p-text-md,16px);
  --ds-text-lg:var(--p-text-lg,24px);
  --ds-space-2:var(--p-space-xs,8px);
  --ds-space-3:var(--p-space-sm,12px);
  --ds-space-4:var(--p-space-md,16px);
  --ds-space-6:var(--p-space-lg,24px);
  --ds-space-8:var(--p-space-xl,32px);
}
.ds {
  color:var(--ds-text); background:var(--ds-bg); font:var(--ds-text-md)/1.5 var(--ds-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--ds-text-sm); margin-top:var(--ds-space-3); min-height:20px; color:var(--ds-muted); }
.ds .ds-surface { border:1px solid var(--ds-border); border-radius:var(--ds-radius); background:var(--ds-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--ds-shadow); border-color:#ffffff; }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--ds-inset); background:var(--ds-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--ds-high); box-shadow:0 8px 24px #38465e12; }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--ds-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--ds-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-search-module { container-type:inline-size; }
.ds .ds-search-form { display:grid; grid-template-columns:minmax(0,1fr) minmax(90px,.3fr) auto; align-items:end; gap:var(--ds-space-3); }
.ds .ds-result-count { font-size:var(--ds-text-sm); color:var(--ds-muted); margin-block:var(--ds-space-6) var(--ds-space-4); }
.ds .ds-results { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr)); gap:var(--ds-space-6); }
.ds .ds-empty { padding:var(--ds-space-8); text-align:center; border:1px dashed var(--ds-control-border); border-radius:var(--ds-radius); }
.ds .ds-empty .ds-button { margin-top:var(--ds-space-4); }
.ds .ds-record-detail { padding:var(--ds-space-6); border:1px solid var(--ds-border); border-radius:var(--ds-radius); background:var(--ds-surface); }
.ds .ds-record-detail h3 { font-size:var(--ds-text-lg); font-weight:650; }
.ds .ds-record-detail p { margin-top:var(--ds-space-3); color:var(--ds-muted); }
.ds .ds-record-detail > div { display:flex; flex-wrap:wrap; gap:var(--ds-space-3); margin-top:var(--ds-space-6); }
.ds .ds-record-detail [aria-pressed="true"] { background:var(--ds-success); border-color:var(--ds-success); }
@media(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
@container(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
/* Looks. Labels hidden by a look stay in the page for screen readers. */
.ds .ds-search-module[data-look="pill"] :is(.ds-field > label,.ds-select-field > span),.ds .ds-chip-group > legend,.ds .ds-chip input { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
/* 02 pill: query, status and button share one rounded bar */
.ds .ds-search-module[data-look="pill"] .ds-search-form { grid-template-columns:minmax(0,1fr) auto auto; align-items:center; gap:4px; padding:4px 4px 4px 12px; border:1px solid var(--ds-control-border); border-radius:999px; background:var(--ds-bg); box-shadow:var(--ds-inset); }
.ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-field { grid-column:auto; }
.ds .ds-search-module[data-look="pill"] .ds-search-form .ds-input { border:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="pill"] .ds-search-form select.ds-input { width:auto; padding-inline:12px 8px; border-left:1px solid var(--ds-border); border-radius:0; }
.ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-button { border-radius:999px; }
@container(max-width:420px) { .ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-button { gap:0; padding-inline:12px; font-size:0; } }
/* 03 chips: status as a row of chips under the query */
.ds .ds-search-module[data-look="chips"] .ds-search-form { grid-template-columns:minmax(0,1fr) auto; }
.ds .ds-search-module[data-look="chips"] .ds-search-form > .ds-field { grid-column:auto; }
.ds .ds-chip-group { grid-column:1/-1; order:3; display:flex; flex-wrap:wrap; gap:8px; min-width:0; margin:0; padding:0; border:0; }
.ds .ds-chip { position:relative; display:inline-flex; align-items:center; gap:6px; min-height:44px; padding:0 16px; border:1px solid var(--ds-control-border); border-radius:999px; background:var(--ds-bg); font-size:14px; cursor:pointer; }
.ds .ds-chip:has(:checked) { border-color:var(--ds-accent); background:var(--ds-accent); color:var(--ds-on-accent); font-weight:650; }
.ds .ds-chip:has(:checked)::before { content:'✓'; font-weight:700; }
.ds .ds-chip:has(:focus-visible) { outline:3px solid var(--ds-focus); outline-offset:3px; }
/* list: results as rows instead of tiles */
.ds .ds-search-module[data-look="list"] .ds-results { grid-template-columns:minmax(0,1fr); gap:0; }
.ds .ds-search-module[data-look="list"] .ds-card { flex-flow:row wrap; align-items:center; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="list"] .ds-card-body { flex:1 1 160px; padding:14px 0; }
.ds .ds-search-module[data-look="list"] .ds-card h3 { margin-top:4px; font-size:17px; }
.ds .ds-search-module[data-look="list"] .ds-divider { display:none; }
.ds .ds-search-module[data-look="list"] .ds-card-actions { padding:8px 0 8px 12px; }
.ds .ds-search-module[data-look="list"] .ds-results { border-top:1px solid var(--ds-border); }
.ds .ds-search-module[data-look="list"] .ds-card { border-bottom:1px solid var(--ds-border); }
/* 07 feature: the first result spans the row with a bigger title */
.ds .ds-search-module[data-look="feature"] .ds-results > :first-child { grid-column:1/-1; }
.ds .ds-search-module[data-look="feature"] .ds-results > :first-child h3 { font-size:26px; line-height:1.3; }
/* picker: one field that narrows while typing; every result is a face row tapped as a whole */
.ds .ds-search-module[data-look="picker"] .ds-search-form { grid-template-columns:minmax(0,1fr); }
.ds .ds-search-module[data-look="picker"] .ds-results { grid-template-columns:minmax(0,1fr); gap:0; border-top:1px solid var(--ds-border); }
.ds .ds-search-module[data-look="picker"] .ds-card { position:relative; display:grid; grid-template-columns:44px minmax(0,1fr) auto; align-items:center; gap:var(--ds-space-3); padding:8px 4px; border:0; border-bottom:1px solid var(--ds-border); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="picker"] .ds-card-media { display:grid; place-items:center; flex:none; width:44px; height:44px; margin:0; aspect-ratio:auto; border-radius:50%; background:var(--ds-soft); color:var(--ds-text); font-weight:700; }
.ds .ds-search-module[data-look="picker"] .ds-card-body { display:flex; flex-wrap:wrap; align-items:center; gap:2px 8px; padding:0; min-width:0; }
.ds .ds-search-module[data-look="picker"] .ds-card h3 { order:-1; margin:0; font-size:16px; }
.ds .ds-search-module[data-look="picker"] .ds-card p { flex-basis:100%; margin:0; font-size:13px; }
.ds .ds-search-module[data-look="picker"] .ds-card .ds-divider { display:none; }
.ds .ds-search-module[data-look="picker"] .ds-card-actions { grid-column:auto; padding:0; }
.ds .ds-search-module[data-look="picker"] .ds-card-actions .ds-button::after { content:''; position:absolute; inset:0; }

.ds .ds-field,.ds .ds-select-field { display:grid; gap:var(--ds-space-2); min-width:0; font-size:14px; }
.ds .ds-field > label,.ds .ds-select-field > span { font-weight:600; }
.ds .ds-help { font-size:var(--ds-text-sm); color:var(--ds-muted); line-height:1.5; }
.ds .ds-field[data-state="error"] .ds-help { color:var(--ds-error); }
.ds .ds-field[data-state="error"] .ds-help::before { content:'!'; display:inline-grid; place-items:center; width:14px; height:14px; font-size:11px; border:1px solid currentColor; border-radius:50%; margin-right:5px; }
.ds .ds-field[data-state="success"] .ds-help { color:var(--ds-success); }
.ds .ds-field[data-state="success"] .ds-help::before { content:'✓'; margin-right:5px; }
.ds .ds-field[data-state="success"] .ds-input { border-color:var(--ds-success); }
.ds .ds-field[data-state="focus"] .ds-input { outline:3px solid var(--ds-focus); outline-offset:3px; }
/* looks: layout of label, input and help; input shapes come from the input part */
.ds .ds-field[data-look="inline"] { grid-template-columns:96px minmax(0,1fr); align-items:center; column-gap:var(--ds-space-3); }
.ds .ds-field[data-look="inline"] > .ds-help { grid-column:2; }
.ds .ds-field[data-look][data-state="success"] .ds-input { border-color:var(--ds-success); }
.ds .ds-field[data-look="row"] .ds-input-group > .ds-input { text-align:center; }
.ds .ds-input-join { flex:none; color:var(--ds-muted); }
.ds .ds-field[data-state="success"] .ds-input-group { border-color:var(--ds-success); }
.ds .ds-field[data-state="focus"] .ds-input-group { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ds-field[data-state="focus"] .ds-input-group .ds-input { outline:0; }

.ds .ds-input { display:block; width:100%; min-width:0; min-height:48px; padding:11px 14px; border:1px solid var(--ds-control-border); border-radius:var(--ds-control-radius); background:var(--ds-bg); box-shadow:var(--ds-inset); color:var(--ds-text); font-size:14px; line-height:1.5; }
.ds .ds-input::placeholder { color:var(--ds-muted); opacity:1; }
.ds .ds-input:disabled { opacity:1; box-shadow:none; color:var(--ds-muted); background:var(--ds-disabled); border-color:var(--ds-border); cursor:not-allowed; }
.ds .ds-input[aria-invalid="true"] { border-color:var(--ds-error); border-width:2px; padding:10px 13px; }
.ds label.ds-field { display:grid; gap:var(--ds-space-2); min-width:0; font-size:14px; }
/* looks: the same selector draws a bare input and the input inside a field of that look */
.ds .ds-field[data-look="float"] .ds-input { padding-top:14px; box-shadow:none; }
.ds .ds-field[data-look="float"] { position:relative; gap:0; }
.ds .ds-field[data-look="float"] > label { position:absolute; z-index:1; top:0; left:12px; transform:translateY(-50%); padding:0 6px; background:var(--ds-bg); color:var(--ds-muted); font-size:12px; line-height:1.4; }
.ds :is(.ds-input[data-look],.ds-field[data-look] .ds-input):disabled { background:var(--ds-disabled); border-color:var(--ds-border); color:var(--ds-muted); box-shadow:none; }
.ds :is(.ds-input[data-look],.ds-field[data-look] .ds-input)[aria-invalid="true"] { border-color:var(--ds-error); }
/* looks: the helper a value needs sits inside the same box — clear, unit, or − and + */
.ds .ds-input-group { display:flex; align-items:center; min-width:0; border:1px solid var(--ds-control-border); border-radius:var(--ds-control-radius); background:var(--ds-bg); box-shadow:var(--ds-inset); }
.ds .ds-input-group:focus-within { border-color:var(--ds-accent); box-shadow:0 0 0 1px var(--ds-accent); }
.ds .ds-input-group > .ds-input { flex:1 1 0; min-height:46px; border:0; border-radius:inherit; background:transparent; box-shadow:none; }
.ds .ds-input-group > .ds-input:focus-visible { outline:none; }
.ds .ds-input-tool { display:grid; place-items:center; flex:none; width:44px; height:44px; padding:0; border:0; border-radius:calc(var(--ds-control-radius) - 2px); background:transparent; color:var(--ds-text); font:500 22px/1 var(--ds-font, inherit); cursor:pointer; }
.ds .ds-input-tool:hover:not(:disabled) { background:var(--ds-surface); }
.ds .ds-input-tool:focus-visible { outline-offset:-3px; }
.ds .ds-input-group[data-look="clear"] > .ds-input:placeholder-shown + .ds-input-tool { visibility:hidden; }
.ds .ds-input-group[data-look="unit"] > .ds-input { text-align:right; font-variant-numeric:tabular-nums; }
.ds .ds-input-unit { flex:none; align-self:stretch; min-height:44px; padding:0 12px; border:0; border-left:1px solid var(--ds-border); border-radius:0 var(--ds-control-radius) var(--ds-control-radius) 0; background:transparent; color:var(--ds-text); font:inherit; font-weight:600; }
.ds .ds-input-unit:focus-visible { outline-offset:-3px; }
.ds .ds-input-group[data-look="stepper"] { width:fit-content; }
.ds .ds-input-group[data-look="stepper"] > .ds-input { flex:0 0 64px; padding-inline:4px; text-align:center; font-variant-numeric:tabular-nums; -moz-appearance:textfield; appearance:textfield; }
.ds .ds-input-group[data-look="stepper"] > .ds-input::-webkit-inner-spin-button { -webkit-appearance:none; margin:0; }
.ds .ds-input-group:has(:disabled) { background:var(--ds-disabled); border-color:var(--ds-border); box-shadow:none; color:var(--ds-muted); }
.ds .ds-input-group:has(:disabled) .ds-input-tool { color:var(--ds-muted); cursor:not-allowed; }
.ds .ds-input-group:has([aria-invalid="true"]) { border-color:var(--ds-error); box-shadow:0 0 0 1px var(--ds-error); }

.ds .ds-button { display:inline-flex; justify-content:center; align-items:center; gap:var(--ds-space-2); min-width:48px; min-height:48px; padding:10px 20px; border:1px solid var(--ds-accent); border-radius:var(--ds-control-radius); background:var(--ds-accent); color:var(--ds-on-accent); font-size:14px; font-weight:650; line-height:1.4; box-shadow:0 3px 5px #24314526,inset 0 1px 0 #ffffff24; text-decoration:none; transition:background var(--ds-duration),box-shadow var(--ds-duration); }
.ds .ds-button[data-variant="outline"] { border-color:var(--ds-control-border); color:var(--ds-text); background:var(--ds-surface); box-shadow:var(--ds-raised); }
.ds .ds-button[data-variant="ghost"] { color:var(--ds-text); background:transparent; border-color:transparent; box-shadow:none; }
.ds .ds-button[data-size="sm"] { min-height:44px; min-width:44px; padding:8px 16px; font-size:13px; }
.ds .ds-button[data-size="lg"] { min-height:56px; min-width:56px; padding:14px 24px; font-size:16px; }
.ds .ds-button[data-icon-only] { padding:10px; }
.ds .ds-button:not(:disabled):is(:hover,[data-state="hover"]) { background:color-mix(in srgb,var(--ds-accent) 84%,#000); }
.ds .ds-button[data-variant="outline"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--ds-high); }
.ds .ds-button[data-variant="ghost"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--ds-disabled); }
.ds .ds-button:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:inset 3px 3px 6px #15222f60,inset -1px -1px 3px #ffffff18; }
.ds .ds-button:not([data-variant="primary"]):not(:disabled):is(:active,[data-state="pressed"]) { background:var(--ds-bg); box-shadow:var(--ds-inset); }
.ds .ds-button[data-state="focus"] { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ds-button:disabled { opacity:1; box-shadow:none; background:var(--ds-disabled); border-color:var(--ds-border); color:var(--ds-muted); }
.ds .ds-button[aria-busy="true"] { background:var(--ds-accent); color:var(--ds-on-accent); border-color:var(--ds-accent); }
.ds .ds-spinner { width:16px; height:16px; flex-shrink:0; border:2px solid currentColor; border-right-color:transparent; border-radius:50%; animation:ds-spin .8s linear infinite; }
@keyframes ds-spin { to { transform:rotate(360deg); } }
@media(prefers-reduced-motion:reduce) { .ds .ds-spinner { border-style:dotted; } }
/* looks: primary colors change per look, pill/cta change shape for every variant; disabled keeps the base state */
/* looks: arrangements of actions; colour roles stay on data-variant */
.ds .ds-actions { display:flex; flex-wrap:wrap; align-items:center; gap:var(--ds-space-2); min-width:0; }
.ds .ds-button-count { display:inline-grid; place-items:center; min-width:22px; height:22px; padding:0 6px; border-radius:99px; background:var(--ds-accent); color:var(--ds-on-accent); font-size:12px; font-weight:700; line-height:1; }
.ds .ds-button[data-variant="primary"] .ds-button-count { background:var(--ds-on-accent); color:var(--ds-accent); }
.ds .ds-actions[data-look="hero"] { flex-wrap:nowrap; gap:0; }
.ds .ds-actions[data-look="hero"] > .ds-button:first-child { flex:1 0 auto; margin-right:var(--ds-space-2); padding-inline:16px; white-space:nowrap; }
.ds .ds-actions[data-look="hero"] > .ds-button[data-icon-only] { flex:none; width:44px; min-width:44px; padding:0; }
.ds .ds-actions[data-look="hero"] > .ds-button[data-icon-only] { color:var(--ds-text); }
.ds .ds-actions[data-look="pair"] { justify-content:flex-end; }
.ds .ds-actions[data-look="pair"] > .ds-button { flex:0 1 auto; }
.ds .ds-actions[data-look="bar"] { width:100%; padding:var(--ds-space-3); border-top:1px solid var(--ds-border); background:var(--ds-bg); }
.ds .ds-actions[data-look="bar"] > .ds-button { flex:1; min-height:52px; }

.ds .ds-badge { display:inline-flex; align-items:center; width:fit-content; padding:4px 10px; border:1px solid var(--ds-border); border-radius:99px; background:var(--ds-soft); color:var(--ds-text); font-size:12px; line-height:1.5; font-weight:600; }
.ds .ds-badge[data-tone="success"] { background:#e5f2eb; border-color:#8fb8a5; color:var(--ds-success); }
.ds .ds-badge[data-tone="error"] { background:#f9e8e9; border-color:#d4a2a8; color:var(--ds-error); }
.ds .ds-badge[data-tone="warning"] { background:#f6efd9; border-color:#b9a16f; color:var(--ds-warning); }
/* looks: tone keeps the color, look changes the shape */
.ds .ds-badge[data-look="dot"] { gap:6px; background:var(--ds-bg); }
.ds .ds-badge[data-look="dot"]::before { content:''; width:8px; height:8px; border-radius:50%; background:currentColor; }
.ds .ds-badge[data-look="icon"] { gap:4px; padding-left:8px; }
.ds .ds-badge[data-look="icon"] .ui-icon { width:14px; height:14px; stroke-width:2.4; }

.ds .ds-card { display:flex; flex-direction:column; height:100%; background:var(--ds-surface); border:1px solid var(--ds-border); border-radius:var(--ds-radius); box-shadow:var(--ds-raised); overflow:hidden; }
.ds .ds-card[data-selected="true"] { border-color:var(--ds-success); background:#e7f0eb; }
.ds .ds-card-body { flex:1; padding:var(--ds-space-6); }
.ds .ds-card h3 { font-size:20px; line-height:1.45; font-weight:650; letter-spacing:-.035em; margin-top:var(--ds-space-4); }
.ds .ds-card p { font-size:14px; color:var(--ds-muted); margin-top:var(--ds-space-2); }
.ds .ds-card-actions { display:flex; justify-content:flex-end; padding:var(--ds-space-4) var(--ds-space-6); }
/* Looks: :where keeps each look as weak as the base rule, so a selected card still shows its selected state. */
.ds .ds-card:where([data-look="row"]) { display:grid; grid-template-columns:88px minmax(0,1fr); align-content:start; }
.ds .ds-card:where([data-look="row"]) .ds-card-media { height:auto; aspect-ratio:1; margin:var(--ds-space-6) 0 0 var(--ds-space-6); border-radius:16px; }
.ds .ds-card:where([data-look="row"]) .ds-card-body { padding-left:var(--ds-space-4); }
.ds .ds-card:where([data-look="row"]) :is(.ds-divider,.ds-card-actions) { grid-column:1/-1; }
